{"package_wit": "package etzhayyim:unispsc-25172504@1.0.0;

/// UNSPSC 25172504 — Vehicle batteries
/// Battery procurement: cell chemistry evaluation (NMC, LFP, NCA, solid-state),
/// capacity/voltage/cycle life specs, cell manufacturer and pack assembler assessment,
/// fleet battery RFP generation, total cost of ownership including degradation and warranty.
/// Standards: UN 38.3 (transport of lithium batteries), IEC 62660 (secondary lithium-ion cells),
/// SAE J2464 (abuse testing), EU Battery Regulation (due diligence, recycling, carbon footprint).
/// Risks: critical mineral supply (lithium, cobalt, nickel), thermal runaway safety,
/// recycling compliance (EU/CN/US), second-life liability.

interface vehicle-batteries {
    /// Get battery product specifications (chemistry, capacity Ah, voltage, cycle life, form factor, energy density)
    get-spec: func(params: string) -> result<string, string>;
    /// Search battery variants by manufacturer/chemistry/capacity/form factor
    search-variants: func(params: string) -> result<string, string>;
    /// Evaluate battery supplier (cell manufacturer, pack assembler) — quality, lead time, mineral sourcing
    evaluate-supplier: func(params: string) -> result<string, string>;
    /// Generate battery RFP/RFQ — volume, chemistry requirements, warranty terms, recycling provisions
    generate-rfp: func(params: string) -> result<string, string>;
    /// Record battery procurement event (PO, delivery, incoming inspection, deployment)
    record-procurement: func(params: string) -> result<string, string>;
    /// Get applicable standards (UN 38.3, IEC 62660, SAE J2464, EU Battery Regulation)
    get-standards: func(params: string) -> result<string, string>;
    /// Assess battery procurement risk (mineral supply, thermal runaway, recycling, second-life liability)
    assess-risk: func(params: string) -> result<string, string>;
    /// Get UNSPSC-CPC concordance for this commodity
    get-concordance: func(params: string) -> result<string, string>;
    /// Get regulatory/contractual framework governing battery procurement
    get-contract-info: func(params: string) -> result<string, string>;
}
", "world_wit": "package etzhayyim:unispsc-25172504;

world component {
    include kotodama:runtime/kotodama-component@1.0.0;

    // Contract import — procurement regulatory basis
    import kotodama:contract/agreement@1.0.0;

    // Shared UNSPSC classification + concordance
    import etzhayyim:unispsc-product-classification/classification@1.0.0;
    import etzhayyim:unispsc-product-classification/concordance@1.0.0;
    import etzhayyim:unispsc-product-classification/quality-standards@1.0.0;

    // CPC cross-reference
    import etzhayyim:cpc-product-classification/classification@1.0.0;

    // Commodity-specific capability export
    export etzhayyim:unispsc-25172504/vehicle-batteries@1.0.0;

    // Resource flow
    import etzhayyim:resource-flow/resource-flow@0.1.0;

    // DIV-3 coverage (information/documents)
    import kotodama:div/information@1.0.0;
    import kotodama:div/documents@1.0.0;
}
